import{_ as d,C as s,o as i,c,aj as n,E as r,j as e,a}from"./framework.js";const b=JSON.parse('{"title":"Product Categories | Commerce | Admin CMS","description":"Product categories organize storefront navigation and filters (e.g. \\"Men / Outerwear\\"). Categories can manually or automatically include products, and support parent categories for…","frontmatter":{"title":"Product Categories | Commerce | Admin CMS","description":"Product categories organize storefront navigation and filters (e.g. \\"Men / Outerwear\\"). Categories can manually or automatically include products, and support parent categories for…","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/commerce/product-categories.html"}]]},"headers":[],"relativePath":"cms/commerce/product-categories.md","filePath":"en/cms/commerce/product-categories.md","lastUpdated":1781010536000}'),l={name:"cms/commerce/product-categories.md"};function g(u,t,m,p,h,f){const o=s("DocImage");return i(),c("div",null,[t[0]||(t[0]=n('<h1 id="product-categories" tabindex="-1">Product Categories <a class="header-anchor" href="#product-categories" aria-label="Permalink to &quot;Product Categories&quot;">​</a></h1><blockquote><p>Menu: <strong>Commerce -&gt; Product Categories</strong><br> Deep link: <code>/_Admin/commerce/product-categories?SiteId={siteGuid}</code><br><strong>Create</strong>: <code>/_Admin/commerce/product-categories/create?SiteId=...</code><br><strong>Edit</strong>: <code>/_Admin/commerce/product-categories/edit?SiteId=...&amp;id={categoryId}</code></p></blockquote><p><strong>Product categories</strong> organize storefront navigation and filters (e.g. &quot;Men / Outerwear&quot;). Categories can <strong>manually</strong> or <strong>automatically</strong> include products, and support <strong>parent categories</strong> for hierarchy. Display fields and list columns come from <strong>category custom fields</strong> and <strong>summary fields</strong> in <a href="./settings.html">settings</a>.</p><div class="tip custom-block"><p class="custom-block-title">Relationship with products</p><p>Products can be linked in two places:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><strong>Category list -&gt; Product count</strong></td><td><strong>Manual</strong> category: check products in dialog; <strong>Automatic</strong> category: condition match, dialog read-only</td></tr><tr><td><strong>Product detail</strong></td><td><a href="./product-management-detail.html">Product detail</a> basic info <strong>Categories</strong> field; green <strong>+</strong> to multi-select categories (can coexist with manual maintenance; behavior per implementation)</td></tr></tbody></table></div><h2 id="how-to-open" tabindex="-1">How to Open <a class="header-anchor" href="#how-to-open" aria-label="Permalink to &quot;How to Open&quot;">​</a></h2><ol><li>In the <a href="./../navigation.html#edit-menu">Edit menu</a>, enable <strong>Commerce -&gt; Product Categories</strong> (and the parent <strong>Commerce</strong> group).</li><li>Open <strong>Commerce -&gt; Product Categories</strong> in the left sidebar.</li></ol><h2 id="list-page" tabindex="-1">List Page <a class="header-anchor" href="#list-page" aria-label="Permalink to &quot;List Page&quot;">​</a></h2><p>Path: <code>/_Admin/commerce/product-categories?SiteId=...</code></p><table tabindex="0"><thead><tr><th>Column / Action</th><th>Description</th></tr></thead><tbody><tr><td>Dynamic columns</td><td>From <strong>category custom fields</strong> with <strong>summary field</strong> checked in <a href="./settings.html">settings</a>; if none checked, defaults to first two custom fields. Often includes <strong>Title</strong>, <strong>Image</strong>, etc.</td></tr><tr><td><strong>Tags</strong></td><td>Category tags (if configured)</td></tr><tr><td><strong>Product count</strong></td><td>Green tag shows current product count; click to open <a href="#linked-products-dialog">linked products dialog</a></td></tr><tr><td><strong>Condition</strong></td><td><strong>Manual</strong> shows &quot;Manual&quot;; <strong>Automatic</strong> shows rule summary (field + comparison + value, <strong>AND/OR</strong> between rules)</td></tr><tr><td><strong>Create</strong></td><td>Opens <a href="#create-and-edit-page">create page</a></td></tr><tr><td><strong>Edit</strong></td><td>Row pencil opens edit page</td></tr><tr><td><strong>Sort</strong></td><td>When <strong>two or more</strong> categories exist, row-end <strong>Move</strong> icon; drag table rows to reorder (saved on release)</td></tr><tr><td><strong>Batch delete</strong></td><td>Select rows → toolbar <strong>Delete</strong> → confirm</td></tr></tbody></table>',9)),r(o,{src:"/cms/commerce/product-categories-list.png",alt:"Product categories list: dynamic columns, product count, conditions and create",width:"1120"}),t[1]||(t[1]=e("h3",{id:"linked-products-dialog",tabindex:"-1"},[a("Linked Products Dialog "),e("a",{class:"header-anchor",href:"#linked-products-dialog","aria-label":'Permalink to "Linked Products Dialog"'},"​")],-1)),t[2]||(t[2]=e("p",null,[a("Click "),e("strong",null,"Product count"),a(" tag on list to open; dialog title "),e("strong",null,"Products"),a(".")],-1)),r(o,{src:"/cms/commerce/product-categories-products-dialog.png",alt:"Category linked products dialog: manual category add and remove",width:"960"}),t[3]||(t[3]=n('<table tabindex="0"><thead><tr><th>Category type</th><th>Behavior</th></tr></thead><tbody><tr><td><strong>Manual</strong></td><td>Shows <strong>Add products</strong>; multi-select from all site products; row <strong>Delete</strong> removes link; <strong>Save</strong> writes category product list</td></tr><tr><td><strong>Automatic</strong></td><td>Shows current matched products only; <strong>cannot</strong> add/delete (determined by conditions)</td></tr></tbody></table><p>Table columns usually include featured image, title, variant count, stock, active status, etc. (similar to product list summary fields).</p><h2 id="create-and-edit-page" tabindex="-1">Create and Edit Page <a class="header-anchor" href="#create-and-edit-page" aria-label="Permalink to &quot;Create and Edit Page&quot;">​</a></h2><p>Create and edit are full-screen form + bottom <strong>Cancel / Save</strong> (<code>KBottomBar</code>), same structure; <strong>Category type</strong> (manual/automatic) selectable only on <strong>create</strong>; cannot switch on edit page after save.</p>',4)),r(o,{src:"/cms/commerce/product-categories-create.png",alt:"Create product category: basic info, type and automatic conditions",width:"1120"}),r(o,{src:"/cms/commerce/product-categories-edit.png",alt:"Edit product category: basic info and custom fields",width:"1120"}),t[4]||(t[4]=n('<h3 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h3><p>White card (<code>BasicInfo</code>); multilingual sites have <strong>Multilingual</strong> switch top-right.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Title</strong> (<code>title</code>)</td><td>Required; category display name. Multilingual writes to <code>customData.title</code></td></tr><tr><td><strong>SEO name</strong> (<code>seoName</code>)</td><td>Required; URL-friendly category name, similar rules to product SEO, unique site-wide. <code>SeoName</code> component can generate from title (<code>path=category</code>)</td></tr><tr><td><strong>Image</strong> (<code>image</code>)</td><td>From media library; if Image field has meta template, image metadata can be edited</td></tr><tr><td><strong>Description</strong> (<code>description</code>)</td><td>Rich text; multilingual same as title</td></tr><tr><td><strong>Tags</strong> (<code>tags</code>)</td><td>Create new or select existing category tags</td></tr><tr><td><strong>Parent</strong> (<code>parentId</code>)</td><td>Dropdown to select parent category; clear for top-level</td></tr><tr><td><strong>Active</strong> (<code>active</code>)</td><td>Whether category is enabled</td></tr></tbody></table><p>Display names come from system field configuration in <strong>category custom fields</strong> in <a href="./settings.html">settings</a>.</p><h3 id="custom-fields" tabindex="-1">Custom Fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom Fields&quot;">​</a></h3><p><strong>Category custom fields</strong> (non-system) from <a href="./settings.html">settings</a> rendered by <code>CustomData</code>, below basic info; hidden when no fields.</p><h3 id="category-type-create-only" tabindex="-1">Category Type (create only) <a class="header-anchor" href="#category-type-create-only" aria-label="Permalink to &quot;Category Type (create only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Manual</strong></td><td>Operator checks products in list <a href="#linked-products-dialog">linked products dialog</a>; hint: &quot;Manually add products to this category&quot;</td></tr><tr><td><strong>Automatic</strong></td><td>Match by <strong>conditions</strong> below; existing and future matching products auto-included; hint: &quot;Existing and future products are automatically added based on conditions&quot;</td></tr></tbody></table><p>Selecting <strong>Automatic</strong> shows <strong>Product</strong> condition editor (<code>Condition</code>): multiple rules (field, operator, value), <strong>All (AND)</strong> or <strong>Any (OR)</strong>. Edit page shows condition block only when category is already automatic; rules can be modified.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./product-management.html">Product management</a> · <a href="./product-management-detail.html">Product detail</a></li><li><a href="./product-types.html">Product types</a></li><li><a href="./settings.html">Settings</a> — category custom fields, summary fields</li><li><a href="./">Commerce overview</a></li></ul>',11))])}const C=d(l,[["render",g]]);export{b as __pageData,C as default};
